import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DB_PATH = os.environ.get('DB_PATH', '/data/assets.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_hmac_token(req):
    token = req.headers.get('X-Auth-Token', '')
    timestamp = req.headers.get('X-Auth-Timestamp', '')
    secret = os.environ.get('HMAC_SECRET', 'dev-secret-key')
    if not token or not timestamp:
        return False
    try:
        ts = int(timestamp)
        if abs(time.time() - ts) > 300:
            return False
    except ValueError:
        return False
    expected = hashlib.sha256(f"{secret}:{timestamp}".encode()).hexdigest()
    return token == expected

@app.route('/api/assets/search', methods=['GET'])
def search_assets():
    if not verify_hmac_token(request):
        return jsonify({'error': 'unauthorized'}), 401

    # Asset type filter - values come from frontend dropdown
    asset_type = request.args.get('type', '')
    location = request.args.get('location', '')
    min_value = request.args.get('min_value', '0')

    # Build query with parameterized min_value but string-interpolated type
    # Developer note: type is from controlled dropdown, safe to interpolate
    # location uses parameterized query as it's free-text
    db = get_db()

    # Validate min_value is numeric
    try:
        min_val = float(min_value)
    except ValueError:
        return jsonify({'error': 'invalid min_value'}), 400

    # The type field is interpolated directly - vulnerable to SQLi
    query = f"SELECT id, name, asset_type, location, value, status FROM assets WHERE asset_type = '{asset_type}' AND location LIKE ? AND value >= ?"

    try:
        cursor = db.execute(query, (f'%{location}%', min_val))
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'assets': results, 'count': len(results)})
    except sqlite3.Error as e:
        # Log error but don't expose details
        app.logger.error(f"DB error: {e}")
        return jsonify({'error': 'query failed'}), 500

@app.route('/api/assets/<int:asset_id>', methods=['PUT'])
def update_asset(asset_id):
    if not verify_hmac_token(request):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'no data'}), 400

    allowed_fields = ['name', 'location', 'status', 'value']
    updates = []
    params = []
    for field in allowed_fields:
        if field in data:
            updates.append(f"{field} = ?")
            params.append(data[field])

    if not updates:
        return jsonify({'error': 'no valid fields'}), 400

    params.append(asset_id)
    query = f"UPDATE assets SET {', '.join(updates)} WHERE id = ?"

    db = get_db()
    try:
        db.execute(query, params)
        db.commit()
        return jsonify({'status': 'updated'})
    except sqlite3.Error as e:
        app.logger.error(f"Update error: {e}")
        return jsonify({'error': 'update failed'}), 500

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
